startDecorations({
frame(_client, frame) {
frame.underlay.bleed = 24;
frame.underlay.add(new FrameGlow({ color: '#000000', strength: 0.45, radius: 12 }));
frame.overlay.add(new FrameBorder(frame, { thickness: 2, radius: 12, color: (client) => (client.focused ? '#89b4fa' : '#45475a') }));
},
});
